def group_anagrams(strs: list[str]) -> list[list[str]]:
    # Create a dictionary to store anagrams grouped by their sorted characters
    anagram_dict = {}

    # Iterate over each string in the input list
    for s in strs:
        # Convert the string to a sorted tuple of characters
        sorted_chars = tuple(sorted(s))

        # If the sorted characters are already a key in the dictionary, append the string to the corresponding list
        if sorted_chars in anagram_dict:
            anagram_dict[sorted_chars].append(s)
        else:
            # Otherwise, create a new list with the string and add it to the dictionary with the sorted characters as the key
            anagram_dict[sorted_chars] = [s]

    # Return the list of anagrams for each key in the dictionary
    return list(anagram_dict.values())

