def word_break(s: str, word_dict: list[str]) -> bool:
    # Check if the string is empty or if the first word is in the dictionary
    if not s or s in word_dict:
        return True
    # Iterate through the string to check if the remaining part can be segmented
    for i in range(len(s)):
        # Check if the remaining part can be segmented with the current word
        if word_break(s[i+1:], word_dict):
            return True
    return False
